  ('src-hd-call-restore-promise', 'larkspur-it', 'harbour-dental', 'meeting', 'fathom', 'CALL-20931', 'Recording', 'Monthly check-in', '2026-09-30T13:00:00.000Z', 'https://fathom.example/calls/20931?t=965', '[{"label":"Meeting","value":"Monthly check-in"},{"label":"Date","value":"30 Sept 2026, 14:00"},{"label":"Speaker","value":"Sam Okafor, Larkspur IT"},{"label":"Transcript","value":"00:16:05"}]'::jsonb, 'mtg-hd-0930', '00:16:05', 'msp', 'Sam Okafor', 'We will run a full restore test of the imaging share before the 31st and send you the results.'),
  ('src-hd-call-quote-promise', 'larkspur-it', 'harbour-dental', 'meeting', 'fathom', 'CALL-20931', 'Recording', 'Monthly check-in', '2026-09-30T13:00:00.000Z', 'https://fathom.example/calls/20931?t=1700', '[{"label":"Meeting","value":"Monthly check-in"},{"label":"Date","value":"30 Sept 2026, 14:00"},{"label":"Speaker","value":"Sam Okafor, Larkspur IT"},{"label":"Transcript","value":"00:28:20"}]'::jsonb, 'mtg-hd-0930', '00:28:20', 'msp', 'Sam Okafor', 'I will get you a quote for both by the ninth.'),
  ('src-mtg-hd-0930-000510', 'larkspur-it', 'harbour-dental', 'meeting', 'fathom', 'CALL-20931', 'Recording', 'Monthly check-in', '2026-09-30T13:00:00.000Z', 'https://fathom.example/calls/20931?t=310', '[{"label":"Meeting","value":"Monthly check-in"},{"label":"Date","value":"30 Sept 2026, 14:00"},{"label":"Speaker","value":"Priya Nair, practice manager"},{"label":"Transcript","value":"00:05:10"}]'::jsonb, 'mtg-hd-0930', '00:05:10', 'client', 'Priya Nair', 'We are opening surgery seven in November, so we will need another workstation and the camera set up before then.'),
  ('src-hd-call-restore-ask', 'larkspur-it', 'harbour-dental', 'meeting', 'fathom', 'CALL-20931', 'Recording', 'Monthly check-in', '2026-09-30T13:00:00.000Z', 'https://fathom.example/calls/20931?t=872', '[{"label":"Meeting","value":"Monthly check-in"},{"label":"Date","value":"30 Sept 2026, 14:00"},{"label":"Speaker","value":"Priya Nair, practice manager"},{"label":"Transcript","value":"00:14:32"}]'::jsonb, 'mtg-hd-0930', '00:14:32', 'client', 'Priya Nair', 'If we lost the X-ray images we would have to close for the day. Can we test a restore before the end of the month?'),
  ('src-mtg-hd-0930-002748', 'larkspur-it', 'harbour-dental', 'meeting', 'fathom', 'CALL-20931', 'Recording', 'Monthly check-in', '2026-09-30T13:00:00.000Z', 'https://fathom.example/calls/20931?t=1668', '[{"label":"Meeting","value":"Monthly check-in"},{"label":"Date","value":"30 Sept 2026, 14:00"},{"label":"Speaker","value":"Priya Nair, practice manager"},{"label":"Transcript","value":"00:27:48"}]'::jsonb, 'mtg-hd-0930', '00:27:48', 'client', 'Priya Nair', 'Can you send me a price for replacing the two reception PCs? They are painfully slow.'),
  ('src-hd-call-sspr-promise', 'larkspur-it', 'harbour-dental', 'meeting', 'fathom', 'CALL-20488', 'Recording', 'Monthly check-in', '2026-09-02T13:00:00.000Z', 'https://fathom.example/calls/20488?t=1290', '[{"label":"Meeting","value":"Monthly check-in"},{"label":"Date","value":"2 Sept 2026, 14:00"},{"label":"Speaker","value":"Sam Okafor, Larkspur IT"},{"label":"Transcript","value":"00:21:30"}]'::jsonb, 'mtg-hd-0902', '00:21:30', 'msp', 'Sam Okafor', 'We will turn on self-service password reset for the reception team this month.'),
  ('src-mtg-hd-0902-000340', 'larkspur-it', 'harbour-dental', 'meeting', 'fathom', 'CALL-20488', 'Recording', 'Monthly check-in', '2026-09-02T13:00:00.000Z', 'https://fathom.example/calls/20488?t=220', '[{"label":"Meeting","value":"Monthly check-in"},{"label":"Date","value":"2 Sept 2026, 14:00"},{"label":"Speaker","value":"Priya Nair, practice manager"},{"label":"Transcript","value":"00:03:40"}]'::jsonb, 'mtg-hd-0902', '00:03:40', 'client', 'Priya Nair', 'We are switching reminders to texts from October, so the front desk will be on the phones less.'),
  ('src-mtg-hd-0902-001105', 'larkspur-it', 'harbour-dental', 'meeting', 'fathom', 'CALL-20488', 'Recording', 'Monthly check-in', '2026-09-02T13:00:00.000Z', 'https://fathom.example/calls/20488?t=665', '[{"label":"Meeting","value":"Monthly check-in"},{"label":"Date","value":"2 Sept 2026, 14:00"},{"label":"Speaker","value":"Priya Nair, practice manager"},{"label":"Transcript","value":"00:11:05"}]'::jsonb, 'mtg-hd-0902', '00:11:05', 'client', 'Priya Nair', 'Every time the passwords change, someone on reception is locked out for half the morning.'),
  ('src-mtg-hd-0902-001230', 'larkspur-it', 'harbour-dental', 'meeting', 'fathom', 'CALL-20488', 'Recording', 'Monthly check-in', '2026-09-02T13:00:00.000Z', 'https://fathom.example/calls/20488?t=750', '[{"label":"Meeting","value":"Monthly check-in"},{"label":"Date","value":"2 Sept 2026, 14:00"},{"label":"Speaker","value":"Priya Nair, practice manager"},{"label":"Transcript","value":"00:12:30"}]'::jsonb, 'mtg-hd-0902', '00:12:30', 'client', 'Priya Nair', 'Is there a way they can reset it themselves without calling you?'),
  ('src-mtg-nl-1006-000312', 'larkspur-it', 'northside-legal', 'meeting', 'fathom', 'CALL-21002', 'Recording', 'Monthly check-in', '2026-10-06T10:00:00.000Z', 'https://fathom.example/calls/21002?t=192', '[{"label":"Meeting","value":"Monthly check-in"},{"label":"Date","value":"6 Oct 2026, 11:00"},{"label":"Speaker","value":"Tom Asher, operations director"},{"label":"Transcript","value":"00:03:12"}]'::jsonb, 'mtg-nl-1006', '00:03:12', 'client', 'Tom Asher', 'We have four trainees starting in January, so we will need laptops and accounts ready.'),
  ('src-nl-call-review', 'larkspur-it', 'northside-legal', 'meeting', 'fathom', 'CALL-21002', 'Recording', 'Monthly check-in', '2026-10-06T10:00:00.000Z', 'https://fathom.example/calls/21002?t=527', '[{"label":"Meeting","value":"Monthly check-in"},{"label":"Date","value":"6 Oct 2026, 11:00"},{"label":"Speaker","value":"Tom Asher, operations director"},{"label":"Transcript","value":"00:08:47"}]'::jsonb, 'mtg-nl-1006', '00:08:47', 'client', 'Tom Asher', 'Before we renew we are reviewing every supplier, IT included. I want to see what we have had for the money.'),
  ('src-mtg-nl-1006-000930', 'larkspur-it', 'northside-legal', 'meeting', 'fathom', 'CALL-21002', 'Recording', 'Monthly check-in', '2026-10-06T10:00:00.000Z', 'https://fathom.example/calls/21002?t=570', '[{"label":"Meeting","value":"Monthly check-in"},{"label":"Date","value":"6 Oct 2026, 11:00"},{"label":"Speaker","value":"Tom Asher, operations director"},{"label":"Transcript","value":"00:09:30"}]'::jsonb, 'mtg-nl-1006', '00:09:30', 'client', 'Tom Asher', 'Could you put together what you have done for us this year before we sit down on the renewal?'),
