  ('src-mtg-nl-0918-002140', 'larkspur-it', 'northside-legal', 'meeting', 'fathom', 'CALL-20714', 'Recording', 'Quarterly review', '2026-09-18T09:30:00.000Z', 'https://fathom.example/calls/20714?t=1300', '[{"label":"Meeting","value":"Quarterly review"},{"label":"Date","value":"18 Sept 2026, 10:30"},{"label":"Speaker","value":"Tom Asher, operations director"},{"label":"Transcript","value":"00:21:40"}]'::jsonb, 'mtg-nl-0918', '00:21:40', 'client', 'Tom Asher', 'Can we get that sorted before the insurance renewal?'),
