insert into public.recommendations (id, workspace_id, client_id, status, title, reason, created_at, decided_at, source_ids) values
  ('rec-hd-restore-test', 'larkspur-it', 'harbour-dental', 'draft', 'Run a restore test of the imaging share this week', 'Backups have failed three nights running, and Priya asked for a restore test before the end of the month.', '2026-10-09T06:00:00.000Z', null, array['src-hd-alert-48213', 'src-hd-call-restore-ask']::text[]),
  ('rec-hd-surgery-seven', 'larkspur-it', 'harbour-dental', 'draft', 'Order the surgery seven workstation and camera now', 'Surgery seven opens in November and Priya wants a workstation and camera ready before then; lead times are about three weeks.', '2026-10-01T07:00:00.000Z', null, array['src-mtg-hd-0930-000510']::text[]),
  ('rec-mf-depot-network', 'larkspur-it', 'marlow-freight', 'draft', 'Scope the Eastleigh depot network and quote by 31 Oct', 'Gareth said the depot opens in January and asked for network and wi-fi costs by the end of the month.', '2026-10-05T12:00:00.000Z', null, array['src-mf-call-depot', 'src-mf-floorplan']::text[]),
  ('rec-nl-mfa-date', 'larkspur-it', 'northside-legal', 'draft', 'Send Tom a firm MFA completion date before the supplier review', 'MFA was promised by 2 Oct, 9 accounts still lack it, and Tom is reviewing suppliers before the 30 Nov renewal.', '2026-10-06T12:00:00.000Z', null, array['src-nl-call-mfa-promise', 'src-nl-hudu-mfa', 'src-nl-call-review']::text[]),
  ('rec-csc-extend-disk', 'larkspur-it', 'cedar-street-clinic', 'draft', 'Extend the SQL data disk by 200 GB', 'The disk is 94% full and grows about 2 GB a week, so it fills in roughly three weeks.', '2026-10-09T06:00:00.000Z', null, array['src-csc-alert-48190']::text[]);
